// Tests for core/hull2d. Evidence label: unit tests only. Expected values come from tools/hull2d_ref.py (a Jarvis march with exact integers for
// small and mid sets, a Graham scan for the 65536-point sets, closed forms for the parabola and the square perimeter). Every success test
// uses a scratch array of exactly n words and an output array of exactly n entries, pre-filled with a sentinel: the words of the output at and
// beyond the returned count must still hold the sentinel. Tiny or null buffers appear only for NullArgument, TooLarge, ScratchTooSmall,
// OutputTooSmall and CoordinateRange failures and for n = 0. No test asserts any scratch value after a call. The 65536-point cases are
// sampled patterns, not exhaustive. Time is not measured.
#include <catch2/catch_test_macros.hpp>

